<?php
require_once __DIR__.'/../includes/admin_ui.php';
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM notices WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??'');$id=(int)($_POST['id']??0);$d=[trim($_POST['title']),trim($_POST['description']),$_POST['target'],$_POST['publish_date'],$_POST['expiry_date']?:null];if($id){$pdo->prepare("UPDATE notices SET title=?,description=?,target=?,publish_date=?,expiry_date=? WHERE id=?")->execute([...$d,$id]);audit($pdo,'update','Updated notice #'.$id);go('notices.php','Notice updated successfully');}$pdo->prepare("INSERT INTO notices(title,description,target,publish_date,expiry_date,created_by) VALUES(?,?,?,?,?,?)")->execute([...$d,$_SESSION['user']['id']??null]);audit($pdo,'create','Created notice');go('notices.php','Notice published successfully');}
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$pdo->prepare("DELETE FROM notices WHERE id=?")->execute([$id]);audit($pdo,'delete','Deleted notice #'.$id);go('notices.php','Notice deleted');}
$rows=$pdo->query("SELECT * FROM notices ORDER BY publish_date DESC,id DESC")->fetchAll();
admin_layout('Notices','Publish and maintain school notices for students, parents and staff.');echo '<div class="actions"><button class="btn" data-modal="noticeModal">＋ Create Notice</button></div></div>';flash();
echo '<div class="card"><div class="toolbar"><input class="search" data-search="#noticeTable" placeholder="Search notice or audience"><span class="muted">'.count($rows).' notices</span></div><div class="table-wrap"><table class="table" id="noticeTable"><thead><tr><th>Notice</th><th>Audience</th><th>Publish</th><th>Expiry</th><th>Actions</th></tr></thead><tbody>';
foreach($rows as $r){echo '<tr><td><b>'.e($r['title']).'</b><br><span class="muted">'.e(mb_strimwidth($r['description']??'',0,90,'…')).'</span></td><td><span class="badge">'.e($r['target']).'</span></td><td>'.e($r['publish_date']).'</td><td>'.e($r['expiry_date']??'—').'</td><td class="actions-cell"><a class="btn light small" href="?edit='.$r['id'].'">Edit</a><a class="btn danger small" data-confirm="Delete this notice?" href="?delete='.$r['id'].'">Delete</a></td></tr>';}
echo '</tbody></table></div></div><div class="modal" id="noticeModal"><div class="modal-box"><div class="modal-head"><h2>'.($edit?'Edit Notice':'Create Notice').'</h2><button class="close">×</button></div><form class="form" method="post"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="id" value="'.e((string)($edit['id']??0)).'"><div class="form-grid"><label>Title<input name="title" required value="'.e($edit['title']??'').'"></label><label>Audience<select name="target">'.implode('',array_map(fn($x)=>'<option'.(($edit['target']??'')===$x?' selected':'').'>'.e($x).'</option>',['Everyone','Teachers','Students','Parents','Specific Class','Specific Division'])).'</select></label><label>Publish Date<input type="date" name="publish_date" required value="'.e($edit['publish_date']??date('Y-m-d')).'"></label><label>Expiry Date<input type="date" name="expiry_date" value="'.e($edit['expiry_date']??'').'"></label><label class="form-full">Description<textarea name="description" rows="5" required>'.e($edit['description']??'').'</textarea></label></div><div class="form-actions"><button type="button" class="btn light close">Cancel</button><button class="btn">'.($edit?'Update Notice':'Publish Notice').'</button></div></form></div></div>';if($edit)echo '<script>document.getElementById("noticeModal").classList.add("show")</script>';admin_end();